<?php
namespace App\Models; use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class Employee extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','branch_id','department_id','job_title_id','user_id','employee_number','legal_name','preferred_name','email','phone','address','date_of_birth','joined_on','ended_on','status']; protected function casts():array{return ['date_of_birth'=>'date','joined_on'=>'date','ended_on'=>'date'];} public function company(){return $this->belongsTo(Company::class);} public function branch(){return $this->belongsTo(Branch::class);} public function department(){return $this->belongsTo(Department::class);} public function jobTitle(){return $this->belongsTo(JobTitle::class);} public function contracts(){return $this->hasMany(EmploymentContract::class);} public function salaryAssignments(){return $this->hasMany(EmployeeSalaryAssignment::class);} public function user(){return $this->belongsTo(User::class);} }
